import React, { useContext } from 'react';

import { DocumentOutlineContext } from '../contexts/DocumentOutline.js';
import { HeadingLevel } from '../types/heading.js';
import { WithChildren } from '../types/with-children.js';

/**
 * Provider that can be reused in components that can
 * create another level of hierarchy for the document outline
 * @deprecated Will be removed along with the `Section` component.
 */
export const DocumentOutlineProvider = ({ children }: WithChildren) => {
  const currentLevel = useContext(DocumentOutlineContext) ?? 1;
  // We can use a typecast here since this value can never be anything different.
  // The context is already typed and only accepts valid values and increasing by
  // 1 and capping to 6 also always conforms to the heading levels.
  const childLevel = Math.min(currentLevel + 1, 6) as HeadingLevel;
  return (
    <DocumentOutlineContext.Provider value={childLevel}>
      {children}
    </DocumentOutlineContext.Provider>
  );
};
DocumentOutlineProvider.displayName = 'DocumentOutlineProvider';
